import edu.ucr.cs.bdlab.beast.util.ZipUtil
import java.util.zip.{ZipOutputStream, ZipInputStream, ZipEntry}
import org.apache.hadoop.fs.Path
import java.io.ByteArrayOutputStream

val outPath = new Path(output_dir, "test_stored.zip")
val fs = outPath.getFileSystem(sc.hadoopConfiguration)
val outStream = fs.create(outPath)
val zipStream = new ZipOutputStream(outStream)

val testData = Array[Byte](42, 43, 44, 45, 99)
val filename = "test_file.bin"

// Write the uncompressed file to the ZIP stream
try {
  ZipUtil.putStoredFile(zipStream, filename, testData)
} finally {
  zipStream.close()
}

// Verify the ZIP file contents
val inStream = fs.open(outPath)
val zipInStream = new ZipInputStream(inStream)
var entry: ZipEntry = null
var readData: Array[Byte] = Array.emptyByteArray

try {
  entry = zipInStream.getNextEntry()
  assert(entry != null, "ZIP file is empty")
  assert(entry.getName == filename, s"Expected filename $filename, got ${entry.getName}")
  assert(entry.getMethod == ZipEntry.STORED || entry.getMethod == -1, s"Expected STORED method, got ${entry.getMethod}")

  val baos = new ByteArrayOutputStream()
  val buffer = new Array[Byte](1024)
  var len = zipInStream.read(buffer)
  while (len > 0) {
    baos.write(buffer, 0, len)
    len = zipInStream.read(buffer)
  }
  readData = baos.toByteArray
} finally {
  zipInStream.close()
}

assert(readData.sameElements(testData), "Read data does not match written data")

println(s"__CHECK__ putStoredFile ${readData.mkString("[", ", ", "]")}")

