import org.locationtech.jts.geom.{Envelope, GeometryFactory}
import edu.ucr.cs.bdlab.beast._

val totalCount = featuresRDD.count()

if (totalCount > 0) {
  // Get the bounding box of the entire dataset
  val summary = featuresRDD.summary
  val minX = summary.getMinCoord(0)
  val maxX = summary.getMaxCoord(0)
  val minY = summary.getMinCoord(1)
  val maxY = summary.getMaxCoord(1)

  // Create a query range that covers the left half of the dataset's bounding box
  val midX = minX + (maxX - minX) / 2.0
  val env = new Envelope(minX, midX, minY, maxY)
  val geomFactory = new GeometryFactory()
  val rangeGeom = geomFactory.toGeometry(env)

  // Perform the range query
  val filteredRDD = featuresRDD.rangeQuery(rangeGeom)
  val filteredCount = filteredRDD.count()

  // Verify the result size is logically bounded
  assert(filteredCount <= totalCount, s"Filtered count $filteredCount exceeds total count $totalCount")

  // Verify that the returned features actually intersect the query range
  if (filteredCount > 0) {
    val sample = filteredRDD.take(10)
    val allIntersect = sample.forall(f => f.getGeometry.getEnvelopeInternal.intersects(env))
    assert(allIntersect, "One or more returned features do not intersect the query range")
  }

  println(s"__CHECK__ rangeQuery count=$filteredCount, total=$totalCount")
} else {
  println(s"__CHECK__ rangeQuery count=0, total=0")
}

